import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    rows = data[2:2 + r]
    MOD = 10 ** 9 + 7
    dp = [0] * c
    if rows[0][0] == '.':
        dp[0] = 1
    for i in range(r):
        row = rows[i]
        if i > 0:
            dp[0] = dp[0] if row[0] == '.' else 0
        for j in range(1, c):
            if row[j] == '#':
                dp[j] = 0
            else:
                dp[j] = (dp[j] + dp[j - 1]) % MOD
    print(dp[c - 1] % MOD)

main()

